def subtotal(lines):
    total = 0
    for price, quantity in lines:
        if type(price) is not int or price < 0:
            raise ValueError('price')
        if type(quantity) is not int or quantity < 0:
            raise ValueError('quantity')
        total += price * quantity
    return total

