import unittest
from pricing import subtotal
class Pricing(unittest.TestCase):
    def test_positive(self): self.assertEqual(subtotal([(100,2),(25,4)]),300)
    def test_reject(self):
        with self.assertRaises(ValueError): subtotal([(-1,1)])
if __name__ == '__main__': unittest.main()

